fn set_room(&mut self, r: Room) {
    if self.room != r {
        self.finish_gesture();
        self.playing = false;
        self.room = r;
        self.need_fit = true;
        self.say(format!("Sala {}: {}", r.title(), r.tip()));
    }
}

/// Peso del papel cebolla según la distancia d (1..n).
fn onion_weight(&self, d: u32, _n: u32) -> f32 {
    let w = match self.onion_falloff {
        1 => ONION_MAX_OPACITY * 0.55f32.powi(d as i32 - 1),
        2 => ONION_MAX_OPACITY,
        _ => onion_original_opacity(d),
    };
    (w * self.onion_opacity).clamp(0.0, 1.0)
}

